#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeElement: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = Element

    public static func lift(_ handle: UInt64) throws -> Element {
        return Element(unsafeFromHandle: handle)
    }

    public static func lower(_ value: Element) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Element {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: Element, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeElement_lift(_ handle: UInt64) throws -> Element {
    return try FfiConverterTypeElement.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeElement_lower(_ value: Element) -> UInt64 {
    return FfiConverterTypeElement.lower(value)
}






public protocol PageProtocol: AnyObject, Sendable {
    
    /**
     * Activates this page's target.
     */
