     */
    func clearRequests() async 
    
    /**
     * Moves the mouse to (x, y) and performs a click (down & up) with human-like delays.
     */
    func clickMouse(x: Double, y: Double) async throws  -> Page
    
    /**
     * Closes the page.
     */
    func close() async throws 
    
    /**
     * Returns the full HTML content of the page.
     */
    func content() async throws  -> String
    
    /**
