     */
    func coverageStartCss() async throws 
    
    /**
     * Starts JS coverage collection.
     */
    func coverageStartJs() async throws 
    
    /**
     * Stops CSS coverage collection and returns the result as JSON.
     */
    func coverageStopCss() async throws  -> String
    
    /**
     * Stops JS coverage collection and returns the result as JSON.
     */
    func coverageStopJs() async throws  -> String
    
    /**
     * Returns the page PDF as a base64 string.
     */
    func createPdfStream() async throws  -> String
    
    func decodeBase64(data: String) throws  -> Data
    
    /**
