     */
    func setWindowPosition(x: Int64, y: Int64) async throws 
    
    /**
     * Resizes the window, preserving its position.
     */
    func setWindowSize(width: Int64, height: Int64) async throws 
    
    /**
     * Sets the window state (`normal` | `minimized` | `maximized` | `fullscreen`).
     */
    func setWindowState(state: String) async throws 
    
    /**
