/**
 * A handle to an enabled plugin, exposed to every language.
 */
public protocol PluginHandleProtocol: AnyObject, Sendable {
    
    /**
     * Invoke an op with a JSON-encoded argument object; returns JSON.
     */
    func invoke(op: String, argsJson: String) async throws  -> String
    
    /**
     * The ops this plugin exposes.
     */
    func ops()  -> [String]
    
    /**
     * The plugin's name.
     */
    func pluginName()  -> String
    
}
/**
 * A handle to an enabled plugin, exposed to every language.
 */
open class PluginHandle: PluginHandleProtocol, @unchecked Sendable {
    fileprivate let handle: UInt64

    /// Used to instantiate a [FFIObject] without an actual handle, for fakes in tests, mostly.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public struct NoHandle {
        public init() {}
    }

    // TODO: We'd like this to be `private` but for Swifty reasons,
    // we can't implement `FfiConverter` without making this `required` and we can't
    // make it `required` without making it `public`.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    required public init(unsafeFromHandle handle: UInt64) {
        self.handle = handle
    }

    // This constructor can be used to instantiate a fake object.
    // - Parameter noHandle: Placeholder value so we can have a constructor separate from the default empty one that may be implemented for classes extending [FFIObject].
    //
    // - Warning:
    //     Any object instantiated with this constructor cannot be passed to an actual Rust-backed object. Since there isn't a backing handle the FFI lower functions will crash.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public init(noHandle: NoHandle) {
        self.handle = 0
    }

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public func uniffiCloneHandle() -> UInt64 {
        return try! rustCall { uniffi_xcelerate_fn_clone_pluginhandle(self.handle, $0) }
    }
    // No primary constructor declared for this class.

    deinit {
        if handle == 0 {
            // Mock objects have handle=0 don't try to free them
            return
        }

        try! rustCall { uniffi_xcelerate_fn_free_pluginhandle(handle, $0) }
    }

    

    
    /**
     * Invoke an op with a JSON-encoded argument object; returns JSON.
     */
open func invoke(op: String, argsJson: String)async throws  -> String  {
    return
        try  await uniffiRustCallAsync(
            rustFutureFunc: {
                uniffi_xcelerate_fn_method_pluginhandle_invoke(
                    self.uniffiCloneHandle(),
                    FfiConverterString.lower(op),FfiConverterString.lower(argsJson)
                )
            },
            pollFunc: ffi_xcelerate_rust_future_poll_rust_buffer,
            completeFunc: ffi_xcelerate_rust_future_complete_rust_buffer,
            freeFunc: ffi_xcelerate_rust_future_free_rust_buffer,
            liftFunc: FfiConverterString.lift,
            errorHandler: FfiConverterTypeXcelerateError_lift
        )
}
    
    /**
     * The ops this plugin exposes.
     */
open func ops() -> [String]  {
    return try!  FfiConverterSequenceString.lift(try! rustCall() {
    uniffi_xcelerate_fn_method_pluginhandle_ops(
            self.uniffiCloneHandle(),$0
    )
})
}
    
    /**
     * The plugin's name.
     */
open func pluginName() -> String  {
    return try!  FfiConverterString.lift(try! rustCall() {
    uniffi_xcelerate_fn_method_pluginhandle_plugin_name(
            self.uniffiCloneHandle(),$0
    )
})
}
    

    
}


