public enum XcelerateError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case WsError(message: String)
    
    case SerdeError(message: String)
    
    case CdpResponseError(message: String)
    
    case HttpError(message: String)
    
    case NotFound(message: String)
    
    case InternalError(message: String)
    
    case Unsupported(message: String)
    
    case Plugin(message: String)
    

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

