@_documentation(visibility: private)
#endif
public struct FfiConverterTypeXcelerateError: FfiConverterRustBuffer {
    typealias SwiftType = XcelerateError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> XcelerateError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .WsError(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .SerdeError(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .CdpResponseError(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .HttpError(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .NotFound(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 6: return .InternalError(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 7: return .Unsupported(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 8: return .Plugin(
            message: try FfiConverterString.read(from: &buf)
        )
        

        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: XcelerateError, into buf: inout [UInt8]) {
        switch value {

        

        
        case .WsError(_ /* message is ignored*/):
            writeInt(&buf, Int32(1))
        case .SerdeError(_ /* message is ignored*/):
            writeInt(&buf, Int32(2))
        case .CdpResponseError(_ /* message is ignored*/):
            writeInt(&buf, Int32(3))
        case .HttpError(_ /* message is ignored*/):
            writeInt(&buf, Int32(4))
        case .NotFound(_ /* message is ignored*/):
            writeInt(&buf, Int32(5))
        case .InternalError(_ /* message is ignored*/):
            writeInt(&buf, Int32(6))
        case .Unsupported(_ /* message is ignored*/):
            writeInt(&buf, Int32(7))
        case .Plugin(_ /* message is ignored*/):
            writeInt(&buf, Int32(8))

        
        }
    }
}


